// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address caller, uint256 value, bytes calldata data, address target) public {
        vm.assume(caller != c.owner());
        vm.deal(caller, value);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: value}(abi.encodeWithSelector(c.sendMoney.selector, target, value, data));
        assertTrue(ok == false, "sendMoney should revert for non-owner");
    }
}
